import fs from 'fs';
import path from 'path';

function listClaims() {
  const claimsDir = path.join(__dirname, '../claims');
  const claimFiles = fs.readdirSync(claimsDir).filter(file => file.endsWith('.claim.json'));
  const claims = [];

  for (const file of claimFiles) {
    const filePath = path.join(claimsDir, file);
    const content = fs.readFileSync(filePath, 'utf8');
    const claim = JSON.parse(content);
    claims.push({ claim_id: claim.claim_id, expect: claim.expect });
  }

  claims.sort((a, b) => a.claim_id.localeCompare(b.claim_id));

  for (const { claim_id, expect } of claims) {
    console.log(`${claim_id} ${expect}`);
  }
}

if (process.argv[2] === 'list') {
  listClaims();
  process.exit(0);
}

